<?php
use App\Core\Csrf;
$symbol = match ($store['currency']) { 'USD' => 'US$', 'EUR' => '€', default => 'RD$' };
$font = match ($store['font_family'] ?? 'inter') {
    'serif' => 'Georgia, Cambria, "Times New Roman", serif',
    'system' => 'ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif',
    'poppins' => 'Poppins, Inter, ui-sans-serif, system-ui, sans-serif',
    default => 'Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif',
};
$customerData = [];
foreach (is_array($checkoutCustomer ?? null) ? $checkoutCustomer : [] as $key => $value) {
    $customerData[mb_strtolower(trim((string) $key))] = is_scalar($value) ? trim((string) $value) : '';
}
$customerValue = static function (array $keys) use ($customerData): string {
    foreach ($keys as $key) {
        $value = $customerData[mb_strtolower($key)] ?? '';
        if ($value !== '') {
            return $value;
        }
    }
    return '';
};
$customerName = $customerValue(['nombre', 'nombre_completo', 'name', 'razon_social', 'razón_social']);
$customerPhone = $customerValue(['telefono', 'teléfono', 'celular', 'whatsapp', 'phone']);
$customerEmail = $customerValue(['email', 'correo', 'correo_electronico']);
$customerDocument = $customerValue(['cedula', 'cédula', 'cedula_rnc', 'rnc', 'documento', 'identificacion', 'identificación', 'tax_id']);
$customerAddress = $customerValue(['direccion', 'dirección', 'domicilio', 'address']);
$customerCity = $customerValue(['ciudad', 'municipio', 'provincia', 'sector', 'city']);
?>
