<script>
(()=>{const key='tmp-store-cart-<?= e($store['uid']) ?>',slug=<?= json_encode($store['slug']) ?>,symbol=<?= json_encode($symbol) ?>,csrf=<?= json_encode(Csrf::token()) ?>,shippingCost=<?= json_encode((float)$store['flat_shipping_cost']) ?>,freeThreshold=<?= json_encode((float)$store['free_shipping_threshold']) ?>;let cart={};try{cart=JSON.parse(localStorage.getItem(key)||'{}')||{}}catch(e){}const list=Object.values(cart).filter(i=>i&&i.product&&Number(i.quantity)>0),form=document.querySelector('[data-checkout-form]'),empty=document.querySelector('[data-empty]'),money=n=>symbol+' '+Number(n||0).toLocaleString('es-DO',{minimumFractionDigits:2,maximumFractionDigits:2}),esc=v=>{const d=document.createElement('div');d.textContent=String(v??'');return d.innerHTML},subtotal=list.reduce((s,i)=>s+(Number(i.product.price)||0)*Number(i.quantity),0);if(!list.length){form.hidden=true;empty.hidden=false;return}document.querySelector('[data-items]').innerHTML=list.map(i=>'<div class="item"><div class="thumb">'+(i.product.image?'<img src="'+esc(i.product.image)+'" alt="">':'□')+'</div><div><strong>'+esc(i.product.name)+'</strong><small>Cantidad: '+Number(i.quantity)+'</small></div><div class="item-price">'+money((Number(i.product.price)||0)*Number(i.quantity))+'</div></div>').join('');function update(){const delivery=document.querySelector('[name="delivery_method"]:checked')?.value||'',address=document.querySelector('[data-address-fields]'),shipping=delivery==='shipping'&&!(freeThreshold>0&&subtotal>=freeThreshold)?shippingCost:0;address.hidden=delivery==='pickup';address.querySelector('[name="delivery_address"]').required=delivery!=='pickup';document.querySelector('[data-subtotal]').textContent=money(subtotal);document.querySelector('[data-shipping]').textContent=shipping?money(shipping):'Gratis / a coordinar';document.querySelector('[data-total]').textContent=money(subtotal+shipping)}document.querySelectorAll('[name="delivery_method"]').forEach(r=>r.addEventListener('change',update));update();form.addEventListener('submit',async event=>{event.preventDefault();const button=document.querySelector('[data-submit]'),error=document.querySelector('[data-error]'),data=Object.fromEntries(new FormData(form).entries());data._csrf=csrf;data.items=list.map(i=>({uid:i.product.uid,quantity:Number(i.quantity)}));button.disabled=true;button.textContent='Procesando pedido…';error.style.display='none';try{const response=await fetch('/api/storefront/'+encodeURIComponent(slug)+'/checkout',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify(data)}),result=await response.json();if(!response.ok)throw new Error(result.message||'No fue posible crear el pedido.');window.location.assign(result.data.next_url)}catch(e){error.textContent=e.message;error.style.display='block';button.disabled=false;button.textContent='Confirmar y continuar';error.scrollIntoView({behavior:'smooth',block:'center'})}})})();
